/**
 * MobilePathfindingEngine — custom A* pathfinding on NormalizedNavGraph.
 *
 * Avoids the ngraph.graph dependency by implementing A* directly using
 * the normalized graph structure produced by normalizeNavGraph().
 *
 * Features:
 * - Dual-mode routing: standard vs accessible
 * - Inter-floor traversal via stairs/elevator/ramp connectors
 * - Euclidean heuristic with floor-level penalty
 * - Explicit result types (no exceptions for not-found)
 */

import type { NavFloor, NavNode } from '../../src/shared/types';
import type {
  DirectionStep,
  DirectionsResult,
  NormalizedEdgeRecord,
  NormalizedNavGraph,
  NormalizedNodeRecord,
  PathResult,
  PathSegment,
  RouteMode,
  StepIcon,
} from '../domain/navGraph';

// ============================================================
// Priority Queue (binary heap)
// ============================================================

interface QueueEntry {
  nodeId: string;
  gScore: number;
  fScore: number;
}

/**
 * Min-heap priority queue for A* frontier.
 */
class PriorityQueue {
  private heap: QueueEntry[] = [];

  push(nodeId: string, gScore: number, fScore: number): void {
    this.heap.push({ nodeId, gScore, fScore });
    this.bubbleUp(this.heap.length - 1);
  }

  pop(): QueueEntry | undefined {
    if (this.heap.length === 0) return undefined;
    const min = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0);
    }
    return min;
  }

  isEmpty(): boolean {
    return this.heap.length === 0;
  }

  private bubbleUp(index: number): void {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.heap[parent].fScore <= this.heap[index].fScore) break;
      [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
      index = parent;
    }
  }

  private bubbleDown(index: number): void {
    const length = this.heap.length;
    while (true) {
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      let smallest = index;

      if (left < length && this.heap[left].fScore < this.heap[smallest].fScore) {
        smallest = left;
      }
      if (right < length && this.heap[right].fScore < this.heap[smallest].fScore) {
        smallest = right;
      }
      if (smallest === index) break;
      [this.heap[smallest], this.heap[index]] = [this.heap[index], this.heap[smallest]];
      index = smallest;
    }
  }
}

// ============================================================
// Constants
// ============================================================

/** Weight for inter-floor traversal in standard mode (elevator/ramp) */
const INTER_FLOOR_STANDARD_WEIGHT = 0.3;
/** Weight for inter-floor traversal via elevator in accessible mode */
const INTER_FLOOR_ELEVATOR_WEIGHT = 0.45;
/** Weight for inter-floor traversal via ramp in accessible mode */
const INTER_FLOOR_RAMP_WEIGHT = 0.45;
/** Stairs are not accessible — used as sentinel for inaccessible inter-floor traversal */
const INTER_FLOOR_STAIRS_INACCESSIBLE = Infinity;
/** Penalty multiplier for floor-level difference in heuristic */
const FLOOR_PENALTY_PER_LEVEL = 0.5;

// ============================================================
// Engine
// ============================================================

/**
 * Custom A* pathfinding engine for mobile.
 *
 * Operates directly on NormalizedNavGraph, avoiding ngraph.graph dependency.
 */
export class MobilePathfindingEngine {
  private readonly graph: NormalizedNavGraph;

  constructor(graph: NormalizedNavGraph) {
    this.graph = graph;
  }

  /**
   * Find a route between two nodes.
   *
   * @param fromId - Source node ID
   * @param toId - Destination node ID
   * @param mode - 'standard' or 'accessible'
   * @returns PathResult with found status, ordered nodeIds, segments, and totalDistance
   */
  findRoute(fromId: string, toId: string, mode: RouteMode): PathResult {
    // Trivial same-node case
    if (fromId === toId) {
      return { found: true, nodeIds: [fromId], totalDistance: 0, segments: [] };
    }

    // Node existence guards
    if (!this.graph.nodeById.has(fromId) || !this.graph.nodeById.has(toId)) {
      return { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    }

    const { nodeIds, segments, totalDistance } = this.astar(fromId, toId, mode);

    if (nodeIds.length === 0) {
      return { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    }

    return { found: true, nodeIds, totalDistance, segments };
  }

  /**
   * A* search implementation.
   */
  private astar(
    startId: string,
    goalId: string,
    mode: RouteMode,
  ): { nodeIds: string[]; segments: PathSegment[]; totalDistance: number } {
    const frontier = new PriorityQueue();
    const cameFrom = new Map<string, { nodeId: string; edge: NormalizedEdgeRecord }>();
    const gScore = new Map<string, number>();
    const visited = new Set<string>();

    const startRecord = this.graph.nodeById.get(startId)!;
    const goalRecord = this.graph.nodeById.get(goalId)!;

    const startHeuristic = this.heuristic(startRecord, goalRecord);
    frontier.push(startId, 0, startHeuristic);
    gScore.set(startId, 0);

    while (!frontier.isEmpty()) {
      const current = frontier.pop()!;
      const currentId = current.nodeId;

      // Goal reached — reconstruct path
      if (currentId === goalId) {
        return this.reconstructPath(startId, goalId, cameFrom, mode);
      }

      if (visited.has(currentId)) continue;
      visited.add(currentId);

      const neighbors = this.getNeighbors(currentId, mode);

      for (const { neighborId, edgeRecord, edgeWeight } of neighbors) {
        if (visited.has(neighborId)) continue;

        const tentativeG = (gScore.get(currentId) ?? Infinity) + edgeWeight;

        if (tentativeG < (gScore.get(neighborId) ?? Infinity)) {
          gScore.set(neighborId, tentativeG);
          cameFrom.set(neighborId, { nodeId: currentId, edge: edgeRecord });

          const neighborRecord = this.graph.nodeById.get(neighborId)!;
          const f = tentativeG + this.heuristic(neighborRecord, goalRecord);
          frontier.push(neighborId, tentativeG, f);
        }
      }
    }

    // No path found
    return { nodeIds: [], segments: [], totalDistance: 0 };
  }

  /**
   * Reconstruct path from A* search results.
   */
  private reconstructPath(
    startId: string,
    goalId: string,
    cameFrom: Map<string, { nodeId: string; edge: NormalizedEdgeRecord }>,
    mode: RouteMode,
  ): { nodeIds: string[]; segments: PathSegment[]; totalDistance: number } {
    const nodeIds: string[] = [];
    const segments: PathSegment[] = [];
    let currentId: string | undefined = goalId;
    let totalDistance = 0;

    while (currentId !== undefined) {
      nodeIds.unshift(currentId);

      const prev = cameFrom.get(currentId);
      if (prev === undefined) break;

      const { nodeId: prevId, edge } = prev;
      const distance =
        mode === 'accessible' ? edge.effectiveAccessibleWeight : edge.edge.standardWeight;

      segments.unshift({ fromId: prevId, toId: currentId, distance });
      totalDistance += distance;

      currentId = prevId;
    }

    nodeIds.unshift(startId);
    return { nodeIds, segments, totalDistance };
  }

  /**
   * Get neighbors of a node, including inter-floor connections.
   */
  private getNeighbors(
    nodeId: string,
    mode: RouteMode,
  ): Array<{ neighborId: string; edgeRecord: NormalizedEdgeRecord; edgeWeight: number }> {
    const neighbors: Array<{
      neighborId: string;
      edgeRecord: NormalizedEdgeRecord;
      edgeWeight: number;
    }> = [];

    // Same-floor neighbors via outgoing edges
    const outgoingEdges = this.graph.outgoingEdgesByNodeId.get(nodeId) ?? [];
    for (const edgeRecord of outgoingEdges) {
      if (mode === 'accessible' && !edgeRecord.edge.accessible) {
        // Skip non-accessible edges in accessible mode
        continue;
      }

      const weight = mode === 'accessible' ? edgeRecord.effectiveAccessibleWeight : edgeRecord.edge.standardWeight;

      neighbors.push({
        neighborId: edgeRecord.edge.targetId,
        edgeRecord,
        edgeWeight: weight,
      });

      // Add reverse edge for bidirectional connections
      if (edgeRecord.edge.bidirectional) {
        neighbors.push({
          neighborId: edgeRecord.edge.sourceId,
          edgeRecord,
          edgeWeight: weight,
        });
      }
    }

    // Inter-floor neighbors via connector nodes
    const nodeRecord = this.graph.nodeById.get(nodeId);
    if (nodeRecord) {
      const node = nodeRecord.node;

      // Check for connection to floor above
      if (node.connectsToNodeAboveId && node.connectsToFloorAboveId !== undefined) {
        const aboveNeighborId = node.connectsToNodeAboveId;
        if (this.graph.nodeById.has(aboveNeighborId)) {
          const interFloorWeight = this.interFloorWeight(node.type, 'up', mode);
          const syntheticEdgeRecord: NormalizedEdgeRecord = {
            buildingId: nodeRecord.buildingId,
            floorId: node.floorId,
            edge: {
              id: `interfloor-${nodeId}-${aboveNeighborId}`,
              sourceId: nodeId,
              targetId: aboveNeighborId,
              standardWeight: interFloorWeight,
              accessibleWeight: interFloorWeight,
              accessible: node.type === 'elevator' || node.type === 'ramp',
              bidirectional: true,
            },
            effectiveAccessibleWeight: interFloorWeight,
          };

          neighbors.push({
            neighborId: aboveNeighborId,
            edgeRecord: syntheticEdgeRecord,
            edgeWeight: interFloorWeight,
          });
        }
      }

      // Check for connection to floor below
      if (node.connectsToNodeBelowId && node.connectsToFloorBelowId !== undefined) {
        const belowNeighborId = node.connectsToNodeBelowId;
        if (this.graph.nodeById.has(belowNeighborId)) {
          const interFloorWeight = this.interFloorWeight(node.type, 'down', mode);
          const syntheticEdgeRecord: NormalizedEdgeRecord = {
            buildingId: nodeRecord.buildingId,
            floorId: node.floorId,
            edge: {
              id: `interfloor-${nodeId}-${belowNeighborId}`,
              sourceId: nodeId,
              targetId: belowNeighborId,
              standardWeight: interFloorWeight,
              accessibleWeight: interFloorWeight,
              accessible: node.type === 'elevator' || node.type === 'ramp',
              bidirectional: true,
            },
            effectiveAccessibleWeight: interFloorWeight,
          };

          neighbors.push({
            neighborId: belowNeighborId,
            edgeRecord: syntheticEdgeRecord,
            edgeWeight: interFloorWeight,
          });
        }
      }
    }

    return neighbors;
  }

  /**
   * Calculate weight for inter-floor traversal.
   */
  private interFloorWeight(
    nodeType: string,
    direction: 'up' | 'down',
    mode: RouteMode,
  ): number {
    if (nodeType === 'elevator') {
      return mode === 'accessible' ? INTER_FLOOR_ELEVATOR_WEIGHT : INTER_FLOOR_STANDARD_WEIGHT;
    }
    if (nodeType === 'ramp') {
      return mode === 'accessible' ? INTER_FLOOR_RAMP_WEIGHT : INTER_FLOOR_STANDARD_WEIGHT;
    }
    if (nodeType === 'stairs') {
      return mode === 'accessible' ? INTER_FLOOR_STAIRS_INACCESSIBLE : INTER_FLOOR_STANDARD_WEIGHT;
    }
    // Default fallback
    return mode === 'accessible' ? INTER_FLOOR_STAIRS_INACCESSIBLE : INTER_FLOOR_STANDARD_WEIGHT;
  }

  /**
   * Euclidean heuristic with floor-level penalty.
   * Admissible: never overestimates true cost.
   */
  private heuristic(a: NormalizedNodeRecord, b: NormalizedNodeRecord): number {
    const dx = b.node.x - a.node.x;
    const dy = b.node.y - a.node.y;
    const euclidean = Math.sqrt(dx * dx + dy * dy);
    const floorDiff = Math.abs(b.floorNumber - a.floorNumber);
    return euclidean + floorDiff * FLOOR_PENALTY_PER_LEVEL;
  }
}

/**
 * Direction step generation — pure function, no React dependencies.
 *
 * Ported from src/client/hooks/useRouteDirections.ts with corrected relative imports.
 * Used by mobile routing UI to convert computed paths into human-readable directions.
 */

import type { NavFloor, NavNode } from '../../src/shared/types';
import type { DirectionsResult, DirectionStep, PathResult, RouteMode, StepIcon } from '../domain/navGraph';

// ============================================================
// Constants
// ============================================================

const WALKING_SPEED_STANDARD = 0.023; // normalized units/s
const WALKING_SPEED_ACCESSIBLE = 0.013; // normalized units/s

/** Node types that are visible/searchable destinations — eligible for landmark references */
const LANDMARK_TYPES = new Set(['room', 'landmark', 'entrance', 'elevator', 'restroom']);

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute compass bearing in degrees (0–360) from point A to point B.
 * Uses screen-space convention: x increases right, y increases down.
 * atan2(dx, -dy) gives a bearing where 0°=north, 90°=east, 180°=south, 270°=west.
 */
function bearing(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;
  // atan2(x, -y) → clockwise from north in screen-space
  const rad = Math.atan2(dx, -dy);
  const deg = (rad * 180) / Math.PI;
  return (deg + 360) % 360;
}

/**
 * Normalize an angle difference to the range [-180, 180].
 */
function normalizeDelta(delta: number): number {
  let d = delta % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

/**
 * Euclidean distance between two normalized coordinate points.
 */
function euclideanDist(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Resolve a floor number from floor metadata, falling back to floorId when metadata is missing.
 */
function resolveFloorNumber(floorId: number, floorMap: Map<number, NavFloor>): number {
  return floorMap.get(floorId)?.floorNumber ?? floorId;
}

/**
 * Determine vertical movement direction between two floors.
 * Uses resolved floor numbers first; if tied, falls back to floorId to keep output deterministic.
 */
function getVerticalDirection(
  fromFloorId: number,
  toFloorId: number,
  floorMap: Map<number, NavFloor>,
): 'up' | 'down' {
  const fromFloorNumber = resolveFloorNumber(fromFloorId, floorMap);
  const toFloorNumber = resolveFloorNumber(toFloorId, floorMap);

  if (toFloorNumber > fromFloorNumber) return 'up';
  if (toFloorNumber < fromFloorNumber) return 'down';

  return toFloorId >= fromFloorId ? 'up' : 'down';
}

/**
 * Classify bearing delta into a step icon.
 */
function classifyTurn(
  delta: number,
): Exclude<StepIcon, 'arrive' | 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'> {
  const abs = Math.abs(delta);
  if (abs < 30) return 'straight';
  if (abs < 120) return delta > 0 ? 'turn-right' : 'turn-left';
  return delta > 0 ? 'sharp-right' : 'sharp-left';
}

/**
 * Build the instruction text for a direction step at the current (middle) node.
 * Appends " at the {label}" when the node is a searchable landmark-type.
 */
function buildInstruction(
  icon: Exclude<StepIcon, 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'>,
  node: NavNode,
): string {
  const base: Record<
    Exclude<StepIcon, 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'>,
    string
  > = {
    straight: 'Continue straight',
    'turn-left': 'Turn left',
    'turn-right': 'Turn right',
    'sharp-left': 'Sharp left',
    'sharp-right': 'Sharp right',
    arrive: `Arrive at ${node.label}`,
  };

  const text = base[icon];

  // For non-arrive steps: append landmark reference if the node is a visible, searchable destination
  if (icon !== 'arrive' && LANDMARK_TYPES.has(node.type) && node.searchable) {
    return `${text} at the ${node.label}`;
  }

  return text;
}

// ============================================================
// Core function
// ============================================================

/**
 * Convert an ordered list of node IDs into turn-by-turn walking directions.
 *
 * Algorithm:
 * - 0 or 1 nodes → empty result
 * - 2 nodes → single "arrive" step (no turn to compute)
 * - N nodes → for each triple (prev, curr, next): classify bearing delta → build step
 *             then append final "arrive" step for the last node
 */
export function generateDirections(
  nodeIds: string[],
  nodeMap: Map<string, NavNode>,
  mode: RouteMode,
  floorMap: Map<number, NavFloor> = new Map(),
): DirectionsResult {
  if (nodeIds.length < 2) {
    return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 };
  }

  const speed = mode === 'accessible' ? WALKING_SPEED_ACCESSIBLE : WALKING_SPEED_STANDARD;
  const steps: DirectionStep[] = [];
  let totalDistanceNorm = 0;

  // Process intermediate nodes (all except the first and last)
  for (let i = 1; i < nodeIds.length - 1; i++) {
    const prevId = nodeIds[i - 1];
    const currId = nodeIds[i];
    const nextId = nodeIds[i + 1];

    const prev = nodeMap.get(prevId);
    const curr = nodeMap.get(currId);
    const next = nodeMap.get(nextId);
    if (prev === undefined || curr === undefined || next === undefined) continue;

    const distanceM = euclideanDist(prev.x, prev.y, curr.x, curr.y);
    const durationSec = distanceM / speed;
    const currFloorNumber = resolveFloorNumber(curr.floorId, floorMap);
    const nextFloorNumber = resolveFloorNumber(next.floorId, floorMap);

    // Floor-change detection: check if curr→next crosses a floor boundary
    if (curr.floorId !== next.floorId) {
      const verticalDirection = getVerticalDirection(curr.floorId, next.floorId, floorMap);

      // Determine direction icon based on connector type and vertical direction
      let icon: StepIcon;
      if (curr.type === 'stairs') {
        icon = verticalDirection === 'up' ? 'stairs-up' : 'stairs-down';
      } else if (curr.type === 'elevator') {
        icon = 'elevator';
      } else if (curr.type === 'ramp') {
        icon = 'ramp';
      } else {
        // Fallback: should not occur in a well-formed graph
        icon = verticalDirection === 'up' ? 'stairs-up' : 'stairs-down';
      }

      // Determine connector type name for instruction text
      const connectorTypeName =
        curr.type === 'elevator' ? 'elevator' : curr.type === 'ramp' ? 'ramp' : 'stairs';

      const instruction = `Take the ${connectorTypeName} ${verticalDirection} to Floor ${nextFloorNumber}`;
      const isAccessibleSegment = curr.type === 'elevator' || curr.type === 'ramp';

      steps.push({
        instruction,
        icon,
        distanceM,
        durationSec,
        isAccessibleSegment,
        floorId: curr.floorId,
        floorNumber: currFloorNumber,
      });
      totalDistanceNorm += distanceM;
      continue;
    }

    const inBearing = bearing(prev.x, prev.y, curr.x, curr.y);
    const outBearing = bearing(curr.x, curr.y, next.x, next.y);
    const delta = normalizeDelta(outBearing - inBearing);

    const icon = classifyTurn(delta);
    const instruction = buildInstruction(icon, curr);
    const isAccessibleSegment = curr.type === 'ramp' || curr.type === 'elevator';

    steps.push({
      instruction,
      icon,
      distanceM,
      durationSec,
      isAccessibleSegment,
      floorId: curr.floorId,
      floorNumber: currFloorNumber,
    });
    totalDistanceNorm += distanceM;
  }

  // Final "arrive" step — distance from second-to-last to last node
  const lastPrevId = nodeIds[nodeIds.length - 2];
  const lastId = nodeIds[nodeIds.length - 1];
  const lastPrev = nodeMap.get(lastPrevId);
  const last = nodeMap.get(lastId);
  if (lastPrev === undefined || last === undefined) {
    return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 };
  }

  const arriveDistance = euclideanDist(lastPrev.x, lastPrev.y, last.x, last.y);
  const arriveDuration = arriveDistance / speed;
  const arriveInstruction = buildInstruction('arrive', last);

  steps.push({
    instruction: arriveInstruction,
    icon: 'arrive',
    distanceM: arriveDistance,
    durationSec: arriveDuration,
    isAccessibleSegment: last.type === 'ramp' || last.type === 'elevator',
    floorId: last.floorId,
    floorNumber: resolveFloorNumber(last.floorId, floorMap),
  });

  totalDistanceNorm += arriveDistance;
  const totalDurationSec = steps.reduce((sum, s) => sum + s.durationSec, 0);

  return { steps, totalDistanceNorm, totalDurationSec };
}

// ============================================================
// routesAreIdentical utility
// ============================================================

/**
 * Returns true only if both routes were found and share the exact same ordered node IDs.
 */
export function routesAreIdentical(a: PathResult, b: PathResult): boolean {
  if (!a.found || !b.found) return false;
  if (a.nodeIds.length !== b.nodeIds.length) return false;
  return a.nodeIds.every((id, i) => id === b.nodeIds[i]);
}

import type { NavNode } from '@shared/types'
import { useCallback, useMemo, useState } from 'react'

/* ──────────────── Types ──────────────── */

export interface RouteSelection {
  start: NavNode | null
  destination: NavNode | null
  activeField: 'start' | 'destination'
  bothSelected: boolean
  setStart: (node: NavNode | null) => void
  setDestination: (node: NavNode | null) => void
  setActiveField: (field: 'start' | 'destination') => void
  setFromTap: (node: NavNode) => void
  swap: () => void
  clearStart: () => void
  clearDestination: () => void
  clearAll: () => void
}

/* ──────────────── Hook ──────────────── */

/**
 * Manages route selection state — start (A) and destination (B) nodes.
 *
 * `setFromTap` assigns a tapped node to whichever field `activeField` points to,
 * auto-advancing to the other field afterward. If the tapped node is already the
 * OTHER field, it swaps them instead of duplicating.
 */
export function useRouteSelection(): RouteSelection {
  const [start, setStartState] = useState<NavNode | null>(null)
  const [destination, setDestinationState] = useState<NavNode | null>(null)
  const [activeField, setActiveField] = useState<'start' | 'destination'>('start')

  const setStart = useCallback((node: NavNode | null) => {
    setStartState(node)
    setActiveField('destination')
  }, [])

  const setDestination = useCallback((node: NavNode | null) => {
    setDestinationState(node)
    setActiveField('start')
  }, [])

  const setFromTap = useCallback(
    (node: NavNode) => {
      if (activeField === 'start') {
        // If tapped node is already the destination, swap
        if (destination?.id === node.id) {
          setDestinationState(start)
          setStartState(node)
          setActiveField('destination')
        } else {
          setStartState(node)
          setActiveField('destination')
        }
      } else {
        // activeField === 'destination'
        // If tapped node is already the start, swap
        if (start?.id === node.id) {
          setStartState(destination)
          setDestinationState(node)
          setActiveField('start')
        } else {
          setDestinationState(node)
          setActiveField('start')
        }
      }
    },
    [activeField, start, destination],
  )

  const swap = useCallback(() => {
    if (start === null && destination === null) return
    const prevStart = start
    const prevDest = destination
    setStartState(prevDest)
    setDestinationState(prevStart)
  }, [start, destination])

  const clearStart = useCallback(() => {
    setStartState(null)
    setActiveField('start')
  }, [])

  const clearDestination = useCallback(() => {
    setDestinationState(null)
    setActiveField('destination')
  }, [])

  const clearAll = useCallback(() => {
    setStartState(null)
    setDestinationState(null)
    setActiveField('start')
  }, [])

  const bothSelected = useMemo(() => start !== null && destination !== null, [start, destination])

  return {
    start,
    destination,
    activeField,
    bothSelected,
    setStart,
    setDestination,
    setActiveField,
    setFromTap,
    swap,
    clearStart,
    clearDestination,
    clearAll,
  }
}

import type { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import {
  type NavGraphContractValidationError,
  validateNavGraphPayload,
} from './navGraphSchema';
import type { PathResult, PathSegment, RouteMode } from '../../src/shared/pathfinding/types';

// Re-export pathfinding types so routing module can import everything from domain/navGraph
export type { PathResult, PathSegment, RouteMode };

/**
 * Direction generation types — turn-by-turn step generation.
 *
 * Used by mobile/routing/generateDirections.ts to convert computed paths
 * into human-readable walking instructions.
 */

/**
 * Icon types for direction step visualization.
 * Maps to icons in the mobile UI icon set.
 */
export type StepIcon =
  | 'straight'
  | 'turn-left'
  | 'turn-right'
  | 'sharp-left'
  | 'sharp-right'
  | 'arrive'
  | 'accessible'
  | 'stairs-up'
  | 'stairs-down'
  | 'elevator'
  | 'ramp';

/**
 * A single turn-by-turn direction instruction.
 */
export interface DirectionStep {
  /** Human-readable instruction, e.g. "Turn left at the cafeteria" */
  instruction: string;
  icon: StepIcon;
  /** Segment distance in normalized units (0–1 coordinate space) */
  distanceM: number;
  /** Estimated seconds for this segment */
  durationSec: number;
  /** True if this segment passes through a ramp or elevator node */
  isAccessibleSegment: boolean;
  /** Floor ID where this instruction is presented */
  floorId: number;
  /** Resolved floor number for display/grouping; falls back to floorId when metadata is missing */
  floorNumber: number;
}

/**
 * Complete result of direction generation.
 */
export interface DirectionsResult {
  steps: DirectionStep[];
  /** Sum of all segment distances in normalized units */
  totalDistanceNorm: number;
  /** Sum of all step durations in seconds */
  totalDurationSec: number;
}

/**
 * A section of directions on a single floor.
 * Used by mobile/routing/directionSections.ts for floor-grouped display.
 */
export interface DirectionSection {
  floorId: number;
  floorNumber: number;
  steps: DirectionStep[];
}

export interface NormalizedFloorRecord {
  buildingId: number;
  buildingName: string;
  floor: NavFloor;
}

export interface NormalizedNodeRecord {
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
  node: NavNode;
}

export interface NormalizedEdgeRecord {
  buildingId: number;
  floorId: number;
  edge: NavEdge;
  effectiveAccessibleWeight: number;
}

export interface NormalizedNavGraph {
  graph: NavGraph;
  buildingById: Map<number, NavBuilding>;
  floorById: Map<number, NormalizedFloorRecord>;
  floorByBuildingAndNumber: Map<string, NormalizedFloorRecord>;
  nodeById: Map<string, NormalizedNodeRecord>;
  edgeById: Map<string, NormalizedEdgeRecord>;
  outgoingEdgesByNodeId: Map<string, NormalizedEdgeRecord[]>;
}

export type NavGraphNormalizationErrorCode =
  | 'duplicate-building-id'
  | 'duplicate-floor-id'
  | 'duplicate-floor-number-per-building'
  | 'duplicate-node-id'
  | 'duplicate-edge-id'
  | 'node-floor-mismatch'
  | 'edge-node-missing';

export interface NavGraphNormalizationError {
  reason: 'normalization-failure';
  code: NavGraphNormalizationErrorCode;
  message: string;
}

export type NavGraphNormalizationResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphNormalizationError };

export type NavGraphParseAndNormalizeResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphContractValidationError | NavGraphNormalizationError };

function fail(
  code: NavGraphNormalizationErrorCode,
  message: string,
): { ok: false; error: NavGraphNormalizationError } {
  return {
    ok: false,
    error: {
      reason: 'normalization-failure',
      code,
      message,
    },
  };
}

export function floorLookupKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`;
}

export function getEffectiveAccessibleWeight(edge: Pick<NavEdge, 'accessible' | 'accessibleWeight'>): number {
  return edge.accessible ? edge.accessibleWeight : Number.POSITIVE_INFINITY;
}

export function normalizeNavGraph(graph: NavGraph): NavGraphNormalizationResult {
  const buildingById = new Map<number, NavBuilding>();
  const floorById = new Map<number, NormalizedFloorRecord>();
  const floorByBuildingAndNumber = new Map<string, NormalizedFloorRecord>();
  const nodeById = new Map<string, NormalizedNodeRecord>();
  const edgeById = new Map<string, NormalizedEdgeRecord>();
  const outgoingEdgesByNodeId = new Map<string, NormalizedEdgeRecord[]>();

  for (const building of graph.buildings) {
    if (buildingById.has(building.id)) {
      return fail('duplicate-building-id', `Duplicate building id detected: ${building.id}.`);
    }

    buildingById.set(building.id, building);

    for (const floor of building.floors) {
      if (floorById.has(floor.id)) {
        return fail('duplicate-floor-id', `Duplicate floor id detected: ${floor.id}.`);
      }

      const floorKey = floorLookupKey(building.id, floor.floorNumber);
      if (floorByBuildingAndNumber.has(floorKey)) {
        return fail(
          'duplicate-floor-number-per-building',
          `Duplicate floor number ${floor.floorNumber} for building ${building.id}.`,
        );
      }

      const floorRecord: NormalizedFloorRecord = {
        buildingId: building.id,
        buildingName: building.name,
        floor,
      };

      floorById.set(floor.id, floorRecord);
      floorByBuildingAndNumber.set(floorKey, floorRecord);

      for (const node of floor.nodes) {
        if (node.floorId !== floor.id) {
          return fail(
            'node-floor-mismatch',
            `Node ${node.id} reports floorId=${node.floorId}, expected ${floor.id}.`,
          );
        }

        if (nodeById.has(node.id)) {
          return fail('duplicate-node-id', `Duplicate node id detected: ${node.id}.`);
        }

        nodeById.set(node.id, {
          buildingId: building.id,
          buildingName: building.name,
          floorId: floor.id,
          floorNumber: floor.floorNumber,
          node,
        });
      }

      for (const edge of floor.edges) {
        if (edgeById.has(edge.id)) {
          return fail('duplicate-edge-id', `Duplicate edge id detected: ${edge.id}.`);
        }

        const edgeRecord: NormalizedEdgeRecord = {
          buildingId: building.id,
          floorId: floor.id,
          edge,
          effectiveAccessibleWeight: getEffectiveAccessibleWeight(edge),
        };

        edgeById.set(edge.id, edgeRecord);
      }
    }
  }

  for (const edgeRecord of edgeById.values()) {
    const source = nodeById.get(edgeRecord.edge.sourceId);
    const target = nodeById.get(edgeRecord.edge.targetId);

    if (!source || !target) {
      return fail(
        'edge-node-missing',
        `Edge ${edgeRecord.edge.id} references missing node(s): ${edgeRecord.edge.sourceId} -> ${edgeRecord.edge.targetId}.`,
      );
    }

    const currentOutgoing = outgoingEdgesByNodeId.get(source.node.id) ?? [];
    currentOutgoing.push(edgeRecord);
    outgoingEdgesByNodeId.set(source.node.id, currentOutgoing);
  }

  return {
    ok: true,
    data: {
      graph,
      buildingById,
      floorById,
      floorByBuildingAndNumber,
      nodeById,
      edgeById,
      outgoingEdgesByNodeId,
    },
  };
}

export function parseAndNormalizeNavGraph(payload: unknown): NavGraphParseAndNormalizeResult {
  const validated = validateNavGraphPayload(payload);
  if (!validated.ok) {
    return validated;
  }

  return normalizeNavGraph(validated.data);
}

