/**
 * Route session state machine — pure computation, no React dependencies.
 *
 * Coordinates pathfinding (T01 engine) and direction generation (T01)
 * into a single discriminated union state that drives the UI.
 */

import type { NavNode } from '../../src/shared/types';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
  RouteMode,
} from '../domain/navGraph';
import { MobilePathfindingEngine } from './pathfindingEngine';
import { generateDirections } from './generateDirections';

// ============================================================
// Phase types
// ============================================================

export type RouteSessionPhase =
  | 'idle'
  | 'computing'
  | 'ready'
  | 'no-route'
  | 'error';

// ============================================================
// Discriminated union state types
// ============================================================

export interface RouteSessionIdleState {
  readonly phase: 'idle';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionComputingState {
  readonly phase: 'computing';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionReadyState {
  readonly phase: 'ready';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: PathResult;
  readonly directions: DirectionsResult;
  readonly errorMessage: null;
}

export interface RouteSessionNoRouteState {
  readonly phase: 'no-route';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionErrorState {
  readonly phase: 'error';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: string;
}

/**
 * Discriminated union of all route session states.
 *
 * Discriminant key: `phase`
 *
 * Phase meanings:
 * - `idle`:    No start/destination yet
 * - `computing`: Currently computing (sync, so only an intermediate phase)
 * - `ready`:  Route found — path and directions available
 * - `no-route`: Start & dest selected but no path exists
 * - `error`:  Node not present in graph or other error
 */
export type RouteSessionState =
  | RouteSessionIdleState
  | RouteSessionComputingState
  | RouteSessionReadyState
  | RouteSessionNoRouteState
  | RouteSessionErrorState;

// ============================================================
// Options
// ============================================================

export interface RouteSessionOptions {
  readonly graph: NormalizedNavGraph;
  readonly mode: RouteMode;
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute directions from a found path result.
 * Uses nodeMap and floorMap from the normalized graph.
 */
function computeDirections(
  path: PathResult,
  mode: RouteMode,
  graph: NormalizedNavGraph,
): DirectionsResult {
  return generateDirections(
    path.nodeIds,
    graph.nodeById,
    mode,
    graph.floorById,
  );
}

// ============================================================
// Main computation function
// ============================================================

/**
 * Compute a route session state synchronously.
 *
 * A* is fast enough that no async boundary is needed.
 * The 'computing' phase is included for UI tooling (DevTools)
 * and to make the phase model complete.
 *
 * Transitions:
 * - start === null || destination === null → 'idle'
 * - start/dest valid but not in graph         → 'error'
 * - start/dest in graph, no path found        → 'no-route'
 * - start/dest in graph, path found           → 'ready'
 */
export function computeRouteSession(options: RouteSessionOptions): RouteSessionState {
  const { graph, mode, start, destination } = options;

  // Guard: missing input
  if (start === null || destination === null) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Guard: nodes not in graph
  if (!graph.nodeById.has(start.id) || !graph.nodeById.has(destination.id)) {
    return {
      phase: 'error',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: 'One or both selected nodes are not present in the navigation graph.',
    };
  }

  // Guard: start === destination
  if (start.id === destination.id) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute path
  const engine = new MobilePathfindingEngine(graph);
  const path = engine.findRoute(start.id, destination.id, mode);

  if (!path.found) {
    return {
      phase: 'no-route',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute directions
  const directions = computeDirections(path, mode, graph);

  return {
    phase: 'ready',
    start,
    destination,
    routeMode: mode,
    path,
    directions,
    errorMessage: null,
  };
}

/**
 * useRouteSession — React hook for reactive route session state.
 *
 * Wires together:
 * - start/destination selection (from useRouteSelection)
 * - pathfinding engine (T01 MobilePathfindingEngine)
 * - direction generation (T01 generateDirections)
 *
 * Exposes a discriminated union `sessionState` that the UI
 * can switch on without knowing implementation details.
 */

import { useCallback, useMemo, useState } from 'react';
import type { NavNode } from '../../src/shared/types';
import type { NormalizedNavGraph, RouteMode } from '../domain/navGraph';
import {
  type RouteSessionState,
  type RouteSessionIdleState,
  type RouteSessionReadyState,
  type RouteSessionNoRouteState,
  type RouteSessionErrorState,
  computeRouteSession,
} from './routeSessionState';

// ============================================================
// RouteSelection (from mobile/hooks/useRouteSelection)
// ============================================================

export interface RouteSelection {
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Props
// ============================================================

export interface UseRouteSessionProps {
  readonly graph: NormalizedNavGraph;
  readonly selection: RouteSelection;
}

// ============================================================
// Hook
// ============================================================

/**
 * Reactive route session.
 *
 * `sessionState` is a discriminated union keyed on `phase`:
 *   - 'idle'       → RouteSessionIdleState     (no selection yet)
 *   - 'ready'      → RouteSessionReadyState    (route found, directions ready)
 *   - 'no-route'   → RouteSessionNoRouteState  (selection complete, unreachable)
 *   - 'error'      → RouteSessionErrorState    (invalid node / graph error)
 *
 * `routeMode` tracks 'standard' | 'accessible' independently of selection.
 */
export function useRouteSession({ graph, selection }: UseRouteSessionProps): {
  sessionState: RouteSessionState;
  routeMode: RouteMode;
  setRouteMode: (mode: RouteMode) => void;
} {
  const [routeMode, setRouteModeState] = useState<RouteMode>('standard');

  const setRouteMode = useCallback((mode: RouteMode) => {
    setRouteModeState(mode);
  }, []);

  const sessionState = useMemo<RouteSessionState>(() => {
    return computeRouteSession({
      graph,
      mode: routeMode,
      start: selection.start,
      destination: selection.destination,
    });
    // Re-compute whenever any input changes
  }, [graph, routeMode, selection.start, selection.destination]);

  return { sessionState, routeMode, setRouteMode };
}

// ============================================================
// Type exports for consumers
// ============================================================

export type { RouteSessionState, RouteSessionIdleState, RouteSessionReadyState, RouteSessionNoRouteState, RouteSessionErrorState };

/**
 * Tests for useRouteSession hook.
 *
 * Covers:
 * - idle state when no selection
 * - computing→ready on valid route
 * - no-route when unreachable
 * - error state for invalid nodes
 * - accessible mode filtering
 */

import { describe, expect, it, vi } from 'vitest';
